"use client";

import { ReactNode } from "react";
import { BeneficiarioProvider } from "@/app/contexts/BeneficiarioContext";

export default function BeneficiarioLayout({
  children,
}: {
  children: ReactNode;
}) {
  return (
    <BeneficiarioProvider>
      {children}
    </BeneficiarioProvider>
  );
}
